// Helper functions
export function getEntityTable(entity: EntityName): string {
  return ENTITY_TABLES[entity];
}

export function getEntityConfig(entity: EntityName): EntityConfig {
  return ENTITY_CONFIGS[entity];
}

export function isTenantEntity(entity: EntityName): boolean {
  return ENTITY_CONFIGS[entity].tenancy === 'tenant';
}

export function isLocationScoped(entity: EntityName): boolean {
  return ENTITY_CONFIGS[entity].locationScoped;
}

export function isEmployeeScoped(entity: EntityName): boolean {
  return ENTITY_CONFIGS[entity].employeeScoped;
}
